html:
{%- set co = frappe.db.get_single_value("Weighbridge Settings", "report_company_name") or "राजदत्त ॲग्रो इंडस्ट्री" -%}
{%- set addr = frappe.db.get_single_value("Weighbridge Settings", "report_address") or "गट नं. ५८४, मु. पो. अपशिंगे (रहिमतपूर), ता. कोरेगांव - ४१५ ५११, जि. सातारा (महाराष्ट्र)" -%}
{%- set t = namespace(routes=[], gross_qty=0, gross_amt=0, binding_kg=0, binding_amt=0, other_kg=0) -%}
{%- for s in doc.slips -%}
 {%- set route = s.route or frappe.db.get_value("Weighment Slip", s.slip, "route") -%}
 {%- if route and route not in t.routes -%}{%- set t.routes = t.routes + [route] -%}{%- endif -%}
 {%- set gross = s.gross_quantity or ((s.cane_weight or 0) / 1000) -%}
 {%- set t.gross_qty = t.gross_qty + gross -%}
 {%- set t.gross_amt = t.gross_amt + (gross * (s.rate or 0))|round(2) -%}
 {%- set t.binding_kg = t.binding_kg + (s.mat_weight or 0) -%}
 {%- set t.binding_amt = t.binding_amt + ((s.mat_weight or 0) / 1000 * (s.rate or 0))|round(2) -%}
 {%- set t.other_kg = t.other_kg + (s.other_deduction or 0) -%}
{%- endfor -%}
{#- what is left after binding is the other deduction, so the three lines always add up to the bill amount -#}
{%- set other_amt = (t.gross_amt - t.binding_amt - (doc.total_amount or 0))|round(2) -%}
{%- set village = (doc.village_name or doc.village or "") ~ ((" ( " ~ t.routes|join(", ") ~ " )") if t.routes else "") -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, precision=2) }}{%- endmacro -%}
{%- macro day(d) -%}{{ frappe.utils.formatdate(d) if d else "" }}{%- endmacro -%}
{%- macro letterhead() -%}
 <table class="lh"><tr>
  <td class="logo"><img src="/assets/vyavantra_weighbridge/images/rajdatt_logo.png"></td>
  <td class="co"><div class="nm">{{ co }}</div><div class="ad">{{ addr }}</div></td>
 </tr></table>
{%- endmacro -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.fbp, .fbp td, .fbp th, .fbp div { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #111; }
.fbp { font-size: 12.5px; line-height: 1.5; }
.fbp table { width: 100%; border-collapse: collapse; }
.fbp .lh td { border: none; vertical-align: middle; padding: 0; }
.fbp .lh .logo { width: 34%; }
.fbp .lh .logo img { height: 44px; }
.fbp .lh .co { text-align: center; }
.fbp .lh .nm { font-size: 21px; font-weight: bold; color: #c0392b; line-height: 1.25; }
.fbp .lh .ad { font-size: 10.5px; }
.fbp .title { text-align: center; font-size: 15px; font-weight: bold; text-decoration: underline; margin: 8px 0 6px; }
.fbp .info td { border: none; padding: 2px 4px; vertical-align: top; }
.fbp .info .l { width: 1%; white-space: nowrap; padding-right: 10px; }
.fbp .info .c { width: 1%; text-align: center; }
.fbp .info .v { font-weight: bold; white-space: nowrap; }
.fbp .info .v.left { width: 34%; }
.fbp .rows { margin-top: 8px; border: 1px solid #333; }
.fbp .rows th { border: 1px solid #333; padding: 5px 6px; text-align: center; font-weight: bold; }
.fbp .rows td { border-left: 1px solid #333; border-right: 1px solid #333; padding: 3px 6px; }
.fbp .rows .fill td { height: 22px; }
.fbp .sum td { border: none; padding: 3px 6px; }
.fbp .sum { border: 1px solid #333; border-top: none; }
.fbp .sum .line td { border-bottom: 1px solid #333; }
.fbp .sum .net td { font-weight: bold; font-size: 13.5px; border-top: 1px solid #333; }
.fbp .r { text-align: right; } .fbp .ce { text-align: center; } .fbp .b { font-weight: bold; }
.fbp .cut { border-top: 1px dashed #555; margin: 16px 0 10px; }
.fbp .sign td { border: none; padding: 34px 4px 0; }
</style>
<div class="fbp">
 {{ letterhead() }}
 <div class="title">ऊस हिशोब पावती</div>
 <table class="info">
  <tr><td class="l">पट्टी नंबर</td><td class="c">:</td><td class="v left">{{ doc.name }}</td>
      <td class="l">दिनांक</td><td class="c">:</td><td class="v">{{ day(doc.bill_date) }}</td></tr>
  <tr><td class="l">ऊस मालकाचे नाव</td><td class="c">:</td><td class="v left">{{ doc.farmer_name or "" }}</td>
      <td class="l">कालावधी</td><td class="c">:</td><td class="v">{{ day(doc.from_date) }} TO {{ day(doc.to_date) }}</td></tr>
  <tr><td class="l">ऊस मालकाचे नंबर</td><td class="c">:</td><td class="v left">{{ doc.farmer or "" }}</td>
      <td class="l">गावाचे नाव</td><td class="c">:</td><td class="v">{{ village }}</td></tr>
 </table>

 <table class="rows">
  <thead><tr><th style="width:15%">दिनांक</th><th style="width:20%">वाहन नंबर</th><th style="width:20%">स्लिप नंबर</th><th style="width:25%">एकूण उसाचे टनेज</th><th style="width:20%">एकूण रक्कम</th></tr></thead>
  <tbody>
  {% for s in doc.slips %}
   <tr><td class="ce">{{ day(s.slip_date) }}</td><td class="ce">{{ s.vehicle or "" }}</td><td class="ce">{{ s.slip or "" }}</td>
       {% set gross = s.gross_quantity or ((s.cane_weight or 0) / 1000) %}<td class="r">{{ "%.3f"|format(gross) }} ({{ money(s.rate) }})</td><td class="r">{{ money((gross * (s.rate or 0))|round(2)) }}</td></tr>
  {% endfor %}
  {% for i in range([6 - doc.slips|length, 1]|max) %}<tr class="fill"><td></td><td></td><td></td><td></td><td></td></tr>{% endfor %}
  </tbody>
 </table>
 <table class="sum">
  <tr class="line"><td style="width:55%"></td><td class="r b" style="width:25%">{{ "%.3f"|format(t.gross_qty) }}</td><td class="r b" style="width:20%">{{ money(t.gross_amt) }}</td></tr>
  <tr class="line"><td>वाढे</td><td class="r">{{ t.binding_kg|int }} KG</td><td class="r">- {{ money(t.binding_amt) }}</td></tr>
  <tr><td>इतर कपात</td><td class="r">{{ t.other_kg|int }} KG</td><td class="r">- {{ money(other_amt) }}</td></tr>
  <tr class="net"><td></td><td class="r">एकूण रक्कम</td><td class="r">{{ money(doc.total_amount) }}</td></tr>
 </table>

 <div class="cut"></div>

 {{ letterhead() }}
 <div class="title">नावेचे चलन</div>
 <table class="info">
  <tr><td class="l">शेतकऱ्याचे नाव</td><td class="c">:</td><td class="v left">{{ doc.farmer_name or "" }}</td>
      <td class="l">गांव</td><td class="c">:</td><td class="v">{{ village }}</td></tr>
  <tr><td class="l">एकूण रक्कम रुपये</td><td class="c">:</td><td class="v left">{{ money(doc.total_amount) }}</td>
      <td class="l">बिल नंबर</td><td class="c">:</td><td class="v">{{ doc.name }} &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {{ day(doc.bill_date) }}</td></tr>
  <tr><td class="l">रोख / चेक नंबर</td><td class="c">:</td><td class="v left"></td><td></td><td></td><td></td></tr>
 </table>
 <table class="sign"><tr><td style="width:50%">क्लार्कची सही :</td><td>शेतकऱ्याची सही :</td></tr></table>
</div>
